    "home.smartBanking": "Intelligentes Banking",
    "home.smartBanking.title": "Eine erstklassige Art, online zu sparen, auszugeben & Geld zu senden",
    "home.smartBanking.description": "Aurora Bank bietet Ihnen eine ausgefeilte, vollständig digitale Möglichkeit, Ihr Geld zu verwalten. Eröffnen Sie ein Konto, vermehren Sie Ihre Ersparnisse und bewegen Sie Gelder weltweit mit Zuversicht.",
    "home.card1.title": "Globale Karten",
    "home.card1.description": "Karten, die auf der ganzen Welt funktionieren. Kaufen Sie online oder offline mit völliger Freiheit ein.",
    "home.card2.title": "Hohe Renditen",
    "home.card2.description": "Höchste Renditen für Ihre Investitionen. Vermehren Sie Ihr Vermögen mit unseren Premium-Sparkonten.",
    "home.card3.title": "Null Gebühren",
    "home.card3.description": "Keine Geldautomatengebühren. Kein Mindestguthaben. Keine Überziehungsgebühren. Behalten Sie mehr von Ihrem hart verdienten Geld.",
    "home.moreAboutUs": "Mehr über uns",
    "home.ourFeature": "Unsere Funktion",
    "home.feature.title": "Zahlungsdienste weltweit",
    "home.feature.description": "Wir bieten eine robuste Infrastruktur für nahtlose globale Zahlungen. Egal, ob Sie Geld an die Familie senden, Ihr Geschäft finanzieren oder Dienstleistungen im Ausland bezahlen, wir helfen Ihnen, Ihre Überweisungen schnell und zuverlässig durchzuführen.",
    "home.feature1.title": "Schützen Sie Ihre Karte",
    "home.feature1.description": "Ihre Kreditkarte ist mit Betrugserkennungs-KI verschlüsselt, um Ihr Geld sicher zu halten.",
    "home.feature2.title": "Geld senden",
    "home.feature2.description": "Senden Sie Geld in nur wenigen Minuten mit niedrigen Gebühren um die ganze Welt.",
    "home.feature3.title": "Online-Banking",
    "home.feature3.description": "Ein neuer Paradigmenwechsel, der die alte Bankenordnung mit unserem Digital-First-Ansatz durchbricht.",
    "home.security": "Bankensicherheit",
    "home.security.title": "Der sicherste Weg, Ihr Geld schnell zu überweisen",
    "home.security.description": "Mit Aurora Bank sind Ihr Geld und Ihre Daten durch mehrschichtige Sicherheit, starke Verschlüsselung und kontinuierliche Betrugsüberwachung geschützt, sodass Sie vertrauensvoll Bankgeschäfte tätigen können.",
    "home.security.encryption": "Verschlüsselung",
    "home.security.monitoring": "Überwachung",
    "home.security.secure": "Sicher",
    "home.security.auth": "Faktor-Auth",

    "about.title": "Über Aurora Bank",
    "about.description": "Aurora Bank ist eine Digital-First-Bank, die für anspruchsvolle Kunden entwickelt wurde, die Einfachheit, Transparenz und Sicherheit auf globaler Ebene erwarten.",
    "about.whoWeAre": "Wer wir sind",
    "about.trustTitle": "Ein Finanzpartner, dem Sie vertrauen können",
    "about.trustText1": "Aurora Bank wurde mit einer einfachen Mission gegründet: modernes Banking anzubieten, das zugänglich und dennoch raffiniert ist und faire Preise mit einem High-Touch-Serviceerlebnis kombiniert. Ihr Geld sollte für Sie arbeiten, nicht in Gebühren und Komplexität verloren gehen.",
    "about.trustText2": "Unsere Spezialisten kombinieren tiefgreifende Finanzexpertise mit fortschrittlicher Technologie, um Ihnen intuitive Tools, aufschlussreiche Beratung und reaktionsschnellen Support zu bieten, wo immer Sie sich auf der Welt befinden.",
    "about.getInTouch": "Kontakt aufnehmen",
    "about.customerFirst": "Kunde zuerst",
    "about.customerFirstText": "Wir priorisieren Ihre Bedürfnisse und Ziele über alles andere.",
    "about.globalReach": "Globale Reichweite",
    "about.globalReachText": "Greifen Sie von überall auf der Welt auf Ihre Gelder und Unterstützung zu.",
    "about.secure": "Sicher & Geschützt",
    "about.secureText": "Erstklassige Verschlüsselung schützt Ihr Vermögen rund um die Uhr.",
    "about.stat.transactions": "Transaktionen",
    "about.stat.countries": "Länder",
    "about.stat.support": "Support",

    "services.title": "Bankdienstleistungen, die auf Sie zugeschnitten sind",
    "services.description": "Vom täglichen Banking bis zu wichtigen Meilensteinen im Leben bietet Aurora Bank maßgeschneiderte Kreditkarten, Kredite und Finanzierungslösungen, um Ihnen zu helfen, sicher voranzukommen.",
    "services.card1.title": "Girokonten",
    "services.card1.description": "Genießen Sie gebührenfreies tägliches Banking mit hohen Transaktionslimits und nahtlosem Zugriff auf mobile Apps.",
    "services.card2.title": "Hochverzinsliche Ersparnisse",
    "services.card2.description": "Sehen Sie zu, wie Ihr Geld mit wettbewerbsfähigen Zinssätzen und ohne Sperrfristen schneller wächst.",
    "services.card3.title": "Unternehmenslösungen",
    "services.card3.description": "Leistungsstarke Tools für Unternehmen jeder Größe, einschließlich Gehaltsabrechnung, Rechnungsstellung und Ausgabenverfolgung.",
    "services.card4.title": "Privatkredite",
    "services.card4.description": "Flexible Privatkredite mit niedrigen effektiven Jahreszinsen, um Ihnen zu helfen, Schulden zu konsolidieren oder Ihre Träume zu finanzieren.",
    "services.card5.title": "Hypotheken",
    "services.card5.description": "Hausfinanzierung einfach gemacht. Lassen Sie sich schnell vorab genehmigen und finden Sie den perfekten Plan für sich.",
    "services.card6.title": "Vermögensverwaltung",
    "services.card6.description": "Expertenrat und Portfoliomanagement zur Sicherung Ihrer finanziellen Zukunft.",
    "services.cta.title": "Bereit loszulegen?",
    "services.cta.description": "Schließen Sie sich Tausenden zufriedener Kunden an, die Aurora Bank für ihre finanzielle Reise vertrauen.",
    "services.cta.button": "Konto eröffnen",

    "contact.title": "Kontaktieren Sie uns",
    "contact.description": "Haben Sie Fragen? Wir sind hier, um zu helfen. Wenden Sie sich rund um die Uhr an unser Team.",
    "contact.getInTouch": "Kontakt aufnehmen",
    "contact.conversationTitle": "Lassen Sie uns ein Gespräch beginnen",
    "contact.conversationText": "Egal, ob Sie eine Frage zu Funktionen, Preisen haben, eine Demo benötigen oder etwas anderes, unser Team ist bereit, alle Ihre Fragen zu beantworten.",
    "contact.email": "E-Mail senden",
    "contact.phone": "Rufen Sie uns an",
    "contact.office": "Besuchen Sie unser Büro",
    "contact.form.name": "Vollständiger Name",
    "contact.form.email": "E-Mail-Adresse",
