    "about.trustTitle": "Финансовый партнер, которому можно доверять",
    "about.trustText1": "Aurora Bank был основан с простой миссией: предложить современный банкинг, который доступен, но изыскан, сочетая справедливые цены с высоким уровнем обслуживания. Ваши деньги должны работать на вас, а не теряться в комиссиях и сложностях.",
    "about.trustText2": "Наши специалисты сочетают глубокую финансовую экспертизу с передовыми технологиями, чтобы предоставить вам интуитивно понятные инструменты, проницательное руководство и отзывчивую поддержку, где бы вы ни находились.",
    "about.getInTouch": "Связаться",
