    "about.title": "Aurora Bankについて",
    "about.description": "Aurora Bankは、世界規模でのシンプルさ、透明性、セキュリティを期待する目の肥えたクライアントのために作られたデジタルファーストの銀行です。",
    "about.whoWeAre": "私たちは誰か",
    "about.trustTitle": "信頼できる金融パートナー",
    "about.trustText1": "Aurora Bankは、シンプルな使命を持って設立されました。それは、公正な価格設定とハイタッチなサービス体験を組み合わせた、アクセスしやすく洗練された最新のバンキングを提供することです。あなたのお金はあなたのために働くべきであり、手数料や複雑さで失われるべきではありません。",
    "about.trustText2": "当社のスペシャリストは、深い金融専門知識と高度な技術を組み合わせて、直感的なツール、洞察に満ちたガイダンス、そして世界中のどこにいても迅速なサポートを提供します。",
    "about.getInTouch": "連絡を取る",
    "about.customerFirst": "顧客第一",
    "about.customerFirstText": "私たちは何よりもあなたのニーズと目標を優先します。",
    "about.globalReach": "グローバルリーチ",
    "about.globalReachText": "地球上のどこからでも資金とサポートにアクセスできます。",
    "about.secure": "安全＆安心",
    "about.secureText": "トップレベルの暗号化により、資産は24時間365日保護されます。",
