    "services.title": "あなたを中心に設計された銀行サービス",
    "services.description": "日常の銀行業務から人生の主要なマイルストーンまで、Aurora Bankはカスタマイズされたクレジットカード、ローン、融資ソリューションを提供し、自信を持って前進できるようにします。",
    "services.card1.title": "当座預金口座",
    "services.card1.description": "高い取引限度額とシームレスなモバイルアプリへのアクセスを備えた手数料無料の日常的な銀行業務をお楽しみください。",
    "services.card2.title": "高利回り貯蓄",
