    "about.title": "Aurora Bank 소개",
    "about.description": "Aurora Bank는 전 세계적인 규모의 단순성, 투명성 및 보안을 기대하는 안목 있는 고객을 위해 만들어진 디지털 우선 은행입니다.",
    "about.whoWeAre": "우리는 누구인가",
    "about.trustTitle": "신뢰할 수 있는 금융 파트너",
    "about.trustText1": "Aurora Bank는 공정한 가격과 하이 터치 서비스 경험을 결합하여 접근 가능하면서도 세련된 현대적인 뱅킹을 제공한다는 단순한 사명으로 설립되었습니다. 귀하의 돈은 귀하를 위해 일해야 하며, 수수료와 복잡성으로 인해 사라져서는 안 됩니다.",
    "about.trustText2": "당사의 전문가들은 깊은 금융 전문 지식과 첨단 기술을 결합하여 전 세계 어디에 있든 직관적인 도구, 통찰력 있는 지침 및 반응형 지원을 제공합니다.",
    "about.getInTouch": "연락하기",
    "about.customerFirst": "고객 최우선",
    "about.customerFirstText": "우리는 무엇보다 귀하의 필요와 목표를 최우선으로 생각합니다.",
    "about.globalReach": "글로벌 도달 범위",
    "about.globalReachText": "지구상 어디에서나 자금과 지원에 액세스하세요.",
    "about.secure": "안전 및 보안",
    "about.secureText": "최고 수준의 암호화로 자산을 연중무휴 24시간 보호합니다.",
    "about.stat.transactions": "거래",
