    "services.title": "귀하를 중심으로 설계된 뱅킹 서비스",
    "services.description": "일상적인 뱅킹부터 인생의 주요 이정표까지, Aurora Bank는 맞춤형 신용 카드, 대출 및 금융 솔루션을 제공하여 자신 있게 나아갈 수 있도록 돕습니다.",
    "services.card1.title": "당좌 계좌",
    "services.card1.description": "높은 거래 한도와 원활한 모바일 앱 액세스로 수수료 없는 일상적인 뱅킹을 즐기세요.",
    "services.card2.title": "고수익 저축",
    "services.card2.description": "경쟁력 있는 이자율과 잠금 기간 없이 돈이 더 빨리 불어나는 것을 지켜보세요.",
    "services.card3.title": "비즈니스 솔루션",
    "services.card3.description": "급여, 송장 발행 및 비용 추적을 포함하여 모든 규모의 기업을 위한 강력한 도구.",
    "services.card4.title": "개인 대출",
    "services.card4.description": "부채를 통합하거나 꿈에 자금을 조달하는 데 도움이 되는 낮은 APR의 유연한 개인 대출.",
    "services.card5.title": "모기지",
    "services.card5.description": "주택 금융이 간편해졌습니다. 빠르게 사전 승인을 받고 완벽한 계획을 찾으세요.",
    "services.card6.title": "자산 관리",
    "services.card6.description": "재정적 미래를 확보하기 위한 전문가의 조언과 포트폴리오 관리.",
    "services.cta.title": "시작할 준비가 되셨나요?",
    "services.cta.description": "금융 여정을 위해 Aurora Bank를 신뢰하는 수천 명의 만족한 고객과 함께하세요.",
    "services.cta.button": "계좌 개설",

