    "home.smartBanking.title": "طريقة متميزة للادخار والإنفاق وإرسال الأموال عبر الإنترنت",
    "home.smartBanking.description": "يمنحك بنك أورورا طريقة متطورة ورقمية بالكامل لإدارة أموالك. افتح حساباً، ونمِّ مدخراتك، وانقل الأموال عالمياً بثقة.",
    "home.card1.title": "بطاقات عالمية",
    "home.card1.description": "بطاقات تعمل في جميع أنحاء العالم. تسوق عبر الإنترنت أو في المتاجر بحرية كاملة.",
    "home.card2.title": "عوائد عالية",
    "home.card2.description": "أعلى العوائد على استثماراتك. نمِّ ثروتك مع حسابات التوفير المتميزة لدينا.",
    "home.card3.title": "بدون رسوم",
    "home.card3.description": "لا رسوم صراف آلي. لا حد أدنى للرصيد. لا رسوم سحب على المكشوف. احتفظ بالمزيد من أموالك التي كسبتها بجهد.",
