    "home.feature.title": "خدمات الدفع حول العالم",
    "home.feature.description": "نحن نوفر بنية تحتية قوية للمدفوعات العالمية السلسة. سواء كنت ترسل الأموال للعائلة، أو تمول عملك، أو تدفع مقابل الخدمات في الخارج، فنحن نساعد تحويلاتك على التحرك بسرعة وموثوقية.",
    "home.feature1.title": "احمِ بطاقتك",
    "home.feature1.description": "بطاقتك الائتمانية مشفرة بذكاء اصطناعي للكشف عن الاحتيال للحفاظ على أمان أموالك.",
    "home.feature2.title": "إرسال الأموال",
