    "about.title": "عن بنك أورورا",
    "about.description": "بنك أورورا هو بنك رقمي أولاً مصمم للعملاء المميزين الذين يتوقعون البساطة والشفافية والأمان على نطاق عالمي.",
    "about.whoWeAre": "من نحن",
    "about.trustTitle": "شريك مالي يمكنك الوثوق به",
    "about.trustText1": "تأسس بنك أورورا بمهمة بسيطة: تقديم خدمات مصرفية حديثة يسهل الوصول إليها ولكنها راقية، تجمع بين التسعير العادل وتجربة خدمة عالية المستوى. يجب أن تعمل أموالك من أجلك، لا أن تضيع في الرسوم والتعقيد.",
    "about.trustText2": "يجمع خبراؤنا بين الخبرة المالية العميقة والتكنولوجيا المتقدمة لمنحك أدوات بديهية، وتوجيهات ثاقبة، ودعماً سريع الاستجابة أينما كنت في العالم.",
    "about.getInTouch": "تواصل معنا",
    "about.customerFirst": "العميل أولاً",
    "about.customerFirstText": "نحن نعطي الأولوية لاحتياجاتك وأهدافك قبل كل شيء.",
    "about.globalReach": "وصول عالمي",
    "about.globalReachText": "الوصول إلى أموالك والدعم من أي مكان على هذا الكوكب.",
    "about.secure": "آمن ومحمي",
    "about.secureText": "التشفير من الدرجة الأولى يحافظ على حماية أصولك على مدار الساعة طوال أيام الأسبوع.",
    "about.stat.transactions": "المعاملات",
    "about.stat.countries": "البلدان",
