    "services.title": "خدمات مصرفية مصممة حولك",
    "services.description": "من الخدمات المصرفية اليومية إلى المعالم الرئيسية في الحياة، يقدم بنك أورورا بطاقات ائتمان وقروض وحلول تمويل مخصصة لمساعدتك على المضي قدماً بثقة.",
    "services.card1.title": "الحسابات الجارية",
    "services.card1.description": "استمتع بخدمات مصرفية يومية خالية من الرسوم مع حدود معاملات عالية ووصول سلس لتطبيقات الهاتف المحمول.",
    "services.card2.title": "توفير عالي العائد",
    "services.card2.description": "شاهد أموالك تنمو بشكل أسرع بأسعار فائدة تنافسية وبدون فترات قفل.",
    "services.card3.title": "حلول الأعمال",
    "services.card3.description": "أدوات قوية للشركات من جميع الأحجام، بما في ذلك كشوف المرتبات والفواتير وتتبع النفقات.",
    "services.card4.title": "القروض الشخصية",
    "services.card4.description": "قروض شخصية مرنة بمعدلات سنوية منخفضة لمساعدتك على توحيد الديون أو تمويل أحلامك.",
    "services.card5.title": "الرهون العقارية",
    "services.card5.description": "تمويل المنازل أصبح بسيطاً. احصل على موافقة مسبقة بسرعة وابحث عن الخطة المثالية لك.",
    "services.card6.title": "إدارة الثروات",
    "services.card6.description": "مشورة الخبراء وإدارة المحافظ لتأمين مستقبلك المالي.",
