    "home.smartBanking.description": "अरोरा बैंक आपको अपने पैसे का प्रबंधन करने का एक परिष्कृत, पूरी तरह से डिजिटल तरीका देता है। खाता खोलें, अपनी बचत बढ़ाएं, और आत्मविश्वास के साथ वैश्विक स्तर पर फंड ट्रांसफर करें।",
