    "home.feature.title": "दुनिया भर में भुगतान सेवाएं",
    "home.feature.description": "हम निर्बाध वैश्विक भुगतान के लिए एक मजबूत बुनियादी ढांचा प्रदान करते हैं। चाहे आप परिवार को पैसे भेज रहे हों, अपने व्यवसाय को निधि दे रहे हों, या विदेश में सेवाओं के लिए भुगतान कर रहे हों, हम आपके स्थानान्तरण को जल्दी और मज़बूती से आगे बढ़ाने में मदद करते हैं।",
