    "about.whoWeAre": "हम कौन हैं",
    "about.trustTitle": "एक वित्तीय भागीदार जिस पर आप भरोसा कर सकते हैं",
    "about.trustText1": "अरोरा बैंक की स्थापना एक सरल मिशन के साथ की गई थी: आधुनिक बैंकिंग की पेशकश करना जो सुलभ अभी तक परिष्कृत है, निष्पक्ष मूल्य निर्धारण को उच्च-स्पर्श सेवा अनुभव के साथ जोड़ती है। आपका पैसा आपके लिए काम करना चाहिए, शुल्क और जटिलता में खो नहीं जाना चाहिए।",
    "about.trustText2": "हमारे विशेषज्ञ आपको सहज ज्ञान युक्त उपकरण, व्यावहारिक मार्गदर्शन और उत्तरदायी समर्थन देने के लिए उन्नत तकनीक के साथ गहरी वित्तीय विशेषज्ञता को जोड़ते हैं, चाहे आप दुनिया में कहीं भी हों।",
