    "home.card3.title": "শূন্য ফি",
    "home.card3.description": "কোন এটিএম ফি নেই। কোন ন্যূনতম ব্যালেন্স নেই। কোন ওভারড্রাফ্ট নেই। আপনার কষ্টার্জিত অর্থের বেশি রাখুন।",
