    "about.trustText1": "অরোরা ব্যাংক একটি সহজ মিশনের সাথে প্রতিষ্ঠিত হয়েছিল: আধুনিক ব্যাংকিং অফার করা যা অ্যাক্সেসযোগ্য কিন্তু পরিশীলিত, ন্যায্য মূল্য নির্ধারণকে উচ্চ-স্পর্শ পরিষেবা অভিজ্ঞতার সাথে একত্রিত করে। আপনার টাকা আপনার জন্য কাজ করা উচিত, ফি এবং জটিলতায় হারিয়ে যাওয়া উচিত নয়।",
    "about.trustText2": "আমাদের বিশেষজ্ঞরা আপনাকে স্বজ্ঞাত সরঞ্জাম, অন্তর্দৃষ্টিপূর্ণ নির্দেশিকা এবং প্রতিক্রিয়াশীল সমর্থন দেওয়ার জন্য উন্নত প্রযুক্তির সাথে গভীর আর্থিক দক্ষতা একত্রিত করেন, আপনি বিশ্বের যেখানেই থাকুন না কেন।",
