    "home.smartBanking": "ਸਮਾਰਟ ਬੈਂਕਿੰਗ",
    "home.smartBanking.title": "ਔਨਲਾਈਨ ਪੈਸੇ ਬਚਾਉਣ, ਖਰਚ ਕਰਨ ਅਤੇ ਭੇਜਣ ਦਾ ਇੱਕ ਪ੍ਰੀਮੀਅਮ ਤਰੀਕਾ",
    "home.smartBanking.description": "ਅਰੋਰਾ ਬੈਂਕ ਤੁਹਾਨੂੰ ਆਪਣੇ ਪੈਸੇ ਦਾ ਪ੍ਰਬੰਧਨ ਕਰਨ ਦਾ ਇੱਕ ਵਧੀਆ, ਪੂਰੀ ਤਰ੍ਹਾਂ ਡਿਜੀਟਲ ਤਰੀਕਾ ਦਿੰਦਾ ਹੈ। ਇੱਕ ਖਾਤਾ ਖੋਲ੍ਹੋ, ਆਪਣੀ ਬਚਤ ਵਧਾਓ, ਅਤੇ ਭਰੋਸੇ ਨਾਲ ਵਿਸ਼ਵਵਿਆਪੀ ਫੰਡ ਟ੍ਰਾਂਸਫਰ ਕਰੋ।",
    "home.card1.title": "ਗਲੋਬਲ ਕਾਰਡ",
    "home.card1.description": "ਕਾਰਡ ਜੋ ਦੁਨੀਆ ਭਰ ਵਿੱਚ ਕੰਮ ਕਰਦੇ ਹਨ। ਪੂਰੀ ਆਜ਼ਾਦੀ ਨਾਲ ਔਨਲਾਈਨ ਜਾਂ ਔਫਲਾਈਨ ਖਰੀਦਦਾਰੀ ਕਰੋ।",
    "home.card2.title": "ਉੱਚ ਰਿਟਰਨ",
    "home.card2.description": "ਤੁਹਾਡੇ ਨਿਵੇਸ਼ਾਂ 'ਤੇ ਸਭ ਤੋਂ ਵੱਧ ਰਿਟਰਨ। ਸਾਡੇ ਪ੍ਰੀਮੀਅਮ ਬਚਤ ਖਾਤਿਆਂ ਨਾਲ ਆਪਣੀ ਦੌਲਤ ਵਧਾਓ।",
    "home.card3.title": "ਜ਼ੀਰੋ ਫੀਸ",
    "home.card3.description": "ਕੋਈ ਏਟੀਐਮ ਫੀਸ ਨਹੀਂ। ਕੋਈ ਘੱਟੋ-ਘੱਟ ਬਕਾਇਆ ਨਹੀਂ। ਕੋਈ ਓਵਰਡਰਾਫਟ ਨਹੀਂ। ਆਪਣੀ ਮਿਹਨਤ ਦੀ ਕਮਾਈ ਨੂੰ ਜ਼ਿਆਦਾ ਰੱਖੋ।",
    "home.moreAboutUs": "ਸਾਡੇ ਬਾਰੇ ਹੋਰ ਜਾਣੋ",
    "home.ourFeature": "ਸਾਡੀ ਵਿਸ਼ੇਸ਼ਤਾ",
    "home.feature.title": "ਦੁਨੀਆ ਭਰ ਵਿੱਚ ਭੁਗਤਾਨ ਸੇਵਾਵਾਂ",
    "home.feature.description": "ਅਸੀਂ ਨਿਰਵਿਘਨ ਵਿਸ਼ਵਵਿਆਪੀ ਭੁਗਤਾਨਾਂ ਲਈ ਇੱਕ ਮਜ਼ਬੂਤ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਪ੍ਰਦਾਨ ਕਰਦੇ ਹਾਂ। ਭਾਵੇਂ ਤੁਸੀਂ ਪਰਿਵਾਰ ਨੂੰ ਪੈਸੇ ਭੇਜ ਰਹੇ ਹੋ, ਆਪਣੇ ਕਾਰੋਬਾਰ ਨੂੰ ਫੰਡ ਦੇ ਰਹੇ ਹੋ, ਜਾਂ ਵਿਦੇਸ਼ ਵਿੱਚ ਸੇਵਾਵਾਂ ਲਈ ਭੁਗਤਾਨ ਕਰ ਰਹੇ ਹੋ, ਅਸੀਂ ਤੁਹਾਡੇ ਟ੍ਰਾਂਸਫਰਾਂ ਨੂੰ ਜਲਦੀ ਅਤੇ ਭਰੋਸੇਯੋਗ ਢੰਗ ਨਾਲ ਅੱਗੇ ਵਧਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰਦੇ ਹਾਂ।",
    "home.feature1.title": "ਆਪਣੇ ਕਾਰਡ ਦੀ ਸੁਰੱਖਿਆ ਕਰੋ",
    "home.feature1.description": "ਤੁਹਾਡਾ ਕ੍ਰੈਡਿਟ ਕਾਰਡ ਤੁਹਾਡੇ ਫੰਡਾਂ ਨੂੰ ਸੁਰੱਖਿਅਤ ਰੱਖਣ ਲਈ ਧੋਖਾਧੜੀ ਦਾ ਪਤਾ ਲਗਾਉਣ ਵਾਲੇ ਏਆਈ ਨਾਲ ਇਨਕ੍ਰਿਪਟ ਕੀਤਾ ਗਿਆ ਹੈ।",
    "home.feature2.title": "ਪੈਸੇ ਭੇਜੋ",
    "home.feature2.description": "ਘੱਟ ਫੀਸਾਂ ਦੇ ਨਾਲ ਕੁਝ ਹੀ ਮਿੰਟਾਂ ਵਿੱਚ ਦੁਨੀਆ ਭਰ ਵਿੱਚ ਪੈਸੇ ਭੇਜੋ।",
    "home.feature3.title": "ਔਨਲਾਈਨ ਬੈਂਕਿੰਗ",
    "home.feature3.description": "ਸਾਡੇ ਡਿਜੀਟਲ-ਪਹਿਲੇ ਦ੍ਰਿਸ਼ਟੀਕੋਣ ਨਾਲ ਪੁਰਾਣੇ ਬੈਂਕਿੰਗ ਆਦੇਸ਼ ਨੂੰ ਭੰਗ ਕਰਨ ਵਾਲਾ ਇੱਕ ਨਵਾਂ ਪੈਰਾਡਾਈਮ ਬਦਲਾਅ।",
    "home.security": "ਬੈਂਕਿੰਗ ਸੁਰੱਖਿਆ",
    "home.security.title": "ਆਪਣੇ ਪੈਸੇ ਨੂੰ ਤੇਜ਼ੀ ਨਾਲ ਲੈਣ-ਦੇਣ ਕਰਨ ਦਾ ਸਭ ਤੋਂ ਸੁਰੱਖਿਅਤ ਤਰੀਕਾ",
    "home.security.description": "ਅਰੋਰਾ ਬੈਂਕ ਦੇ ਨਾਲ, ਤੁਹਾਡਾ ਪੈਸਾ ਅਤੇ ਡੇਟਾ ਬਹੁ-ਪੱਧਰੀ ਸੁਰੱਖਿਆ, ਮਜ਼ਬੂਤ ਇਨਕ੍ਰਿਪਸ਼ਨ ਅਤੇ ਨਿਰੰਤਰ ਧੋਖਾਧੜੀ ਨਿਗਰਾਨੀ ਦੁਆਰਾ ਸੁਰੱਖਿਅਤ ਹੈ, ਤਾਂ ਜੋ ਤੁਸੀਂ ਭਰੋਸੇ ਨਾਲ ਬੈਂਕ ਕਰ ਸਕੋ।",
