    "about.trustText1": "ਅਰੋਰਾ ਬੈਂਕ ਦੀ ਸਥਾਪਨਾ ਇੱਕ ਸਧਾਰਨ ਮਿਸ਼ਨ ਨਾਲ ਕੀਤੀ ਗਈ ਸੀ: ਆਧੁਨਿਕ ਬੈਂਕਿੰਗ ਦੀ ਪੇਸ਼ਕਸ਼ ਕਰਨਾ ਜੋ ਪਹੁੰਚਯੋਗ ਪਰ ਵਧੀਆ ਹੈ, ਨਿਰਪੱਖ ਕੀਮਤ ਨੂੰ ਉੱਚ-ਸਪਰਸ਼ ਸੇਵਾ ਅਨੁਭਵ ਨਾਲ ਜੋੜਦੀ ਹੈ। ਤੁਹਾਡਾ ਪੈਸਾ ਤੁਹਾਡੇ ਲਈ ਕੰਮ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ, ਫੀਸਾਂ ਅਤੇ ਜਟਿਲਤਾ ਵਿੱਚ ਗੁਆਚਿਆ ਨਹੀਂ ਜਾਣਾ ਚਾਹੀਦਾ।",
    "about.trustText2": "ਸਾਡੇ ਮਾਹਰ ਤੁਹਾਨੂੰ ਸਹਿਜ ਸਾਧਨ, ਸੂਝਵਾਨ ਮਾਰਗਦਰਸ਼ਨ ਅਤੇ ਜਵਾਬਦੇਹ ਸਮਰਥਨ ਦੇਣ ਲਈ ਉੱਨਤ ਤਕਨਾਲੋਜੀ ਦੇ ਨਾਲ ਡੂੰਘੀ ਵਿੱਤੀ ਮੁਹਾਰਤ ਨੂੰ ਜੋੜਦੇ ਹਨ, ਭਾਵੇਂ ਤੁਸੀਂ ਦੁਨੀਆ ਵਿੱਚ ਕਿਤੇ ਵੀ ਹੋਵੋ।",
