export type MessageKey = keyof (typeof MESSAGES)["en"];
export type TranslationKey = MessageKey | (string & {});

export function createTranslator(locale: Locale) {
  const selected = (MESSAGES[locale] ?? MESSAGES[defaultLocale]) as Partial<Record<string, string>>;
  const defaults = MESSAGES[defaultLocale] as Record<string, string>;
  return (key: TranslationKey) => {
    return selected[key] ?? defaults[key] ?? key;
  };
}

